// Real-Time Analytics Dashboard - Domain Specialized React Interface
import React, { useState, useEffect } from 'react';

export default function App() {
  const [items, setItems] = useState([
    {
        "id": 1,
        "type": "user_checkout_completed",
        "source": "Storefront Web",
        "eps": 1400,
        "status": "streaming"
    },
    {
        "id": 2,
        "type": "api_latency_heartbeat",
        "source": "API Gateway",
        "eps": 820,
        "status": "streaming"
    },
    {
        "id": 3,
        "type": "fraud_detection_scored",
        "source": "Security Worker",
        "eps": 310,
        "status": "streaming"
    }
]);
  const [newTitle, setNewTitle] = useState('');
  const [newStatus, setNewStatus] = useState('active');
  const [search, setSearch] = useState('');
  const [actionNotice, setActionNotice] = useState('');

  const handleCreate = (e) => {
    e.preventDefault();
    if (!newTitle.trim()) return;
    const newItem = {
      id: items.length + 1,
      title: newTitle,
      name: newTitle,
      status: newStatus,
      description: 'User created operational item',
      created_at: new Date().toISOString()
    };
    setItems([newItem, ...items]);
    setNewTitle('');
    setActionNotice('Created ' + newTitle + ' successfully!');
    setTimeout(() => setActionNotice(''), 3000);
  };

  const handleDelete = (id) => {
    setItems(items.filter(it => it.id !== id));
  };

  const handleTriggerAction = (item) => {
    setActionNotice('Executed action for: ' + (item.title || item.name));
    setTimeout(() => setActionNotice(''), 3000);
  };

  const filtered = items.filter(it => {
    const text = (it.title || it.name || it.description || '').toLowerCase();
    return text.includes(search.toLowerCase());
  });

